    "formula": {
      "type": "labeled-lines",
      "lines": [
        {
          "label": "起點",
          "values": [
            "x^2-kx+1=0\\Rightarrow x+\\frac{1}{x}=k"
          ]
        },
        {
          "label": "平方",
          "values": [
            "\\left(x+\\frac{1}{x}\\right)^2=x^2+2+\\frac{1}{x^2}"
          ]
        },
        {
          "label": "立方",
          "values": [
            "\\left(x+\\frac{1}{x}\\right)^3=x^3+3x+\\frac{3}{x}+\\frac{1}{x^3}"
          ]
        }
      ]
    },
