    "title": "二元一次聯立方程式的幾何意義",
    "formula": {
      "type": "labeled-lines",
      "lines": [
        {
          "label": "相交",
          "values": [
            "\\frac{a_1}{a_2}\\ne\\frac{b_1}{b_2}\\Rightarrow\\text{一解}"
          ]
        },
        {
          "label": "平行",
          "values": [
            "\\frac{a_1}{a_2}=\\frac{b_1}{b_2}\\ne\\frac{c_1}{c_2}\\Rightarrow\\text{無解}"
          ]
        },
        {
          "label": "重合",
          "values": [
            "\\frac{a_1}{a_2}=\\frac{b_1}{b_2}=\\frac{c_1}{c_2}\\Rightarrow\\text{無限多解}"
          ]
        }
      ]
    },
