    "title": "升階降階與加權和",
    "formula": {
      "type": "labeled-lines",
      "lines": [
        {
          "label": "降階",
          "values": [
            "kC_n^k=nC_{n-1}^{k-1}"
          ]
        },
        {
          "label": "升階",
          "values": [
            "\\frac{1}{k+1}C_n^k=\\frac{1}{n+1}C_{n+1}^{k+1}"
          ]
        },
        {
          "label": "加權和",
          "values": [
            "\\sum_{k=1}^{n}kC_n^k=n2^{n-1},\\ \\sum_{k=0}^{n}(2k+1)C_n^k=(n+1)2^n"
          ]
        }
      ]
    },
