    "id": "senior-counting-complement-principle-s221",
    "title": "補集計數與至少一個",
    "formula": {
      "type": "labeled-lines",
      "lines": [
        {
          "label": "補集法",
          "values": [
            "N(\\text{至少一個})=N(\\text{全部})-N(\\text{一個都沒有})"
          ]
        },
        {
          "label": "容斥二集合",
          "values": [
            "|A\\cup B|=|A|+|B|-|A\\cap B|"
          ]
        },
        {
          "label": "容斥三集合",
          "values": [
            "|A\\cup B\\cup C|=\\sum|A_i|-\\sum|A_i\\cap A_j|+|A\\cap B\\cap C|"
          ]
        }
      ]
    },
